3	namespace App\Actions\Subscription;
4	
5	use App\Models\Billing\Plan;
6	use App\Models\Billing\Subscription;
7	use App\Models\Core\Professional\Professional;
8	use App\Services\Stripe\StripeBillingService;
9	use Illuminate\Validation\ValidationException;
10	
11	// V2: Changes professional's subscription plan. Handles free->paid (checkout), paid->paid (Stripe update), and paid->free (cancel + fallback).
12	class ChangeProfessionalPlanAction
13	{
14	    public function __construct(private StripeBillingService $billing) {}
15	
16	    /**
17	     * Change the professional's current plan.
18	     * On paid→paid switches, plan_id and cancel_at_period_end are reconciled
19	     * asynchronously via the customer.subscription.updated webhook.
20	     *
21	     * @return Subscription|array{checkout_url: string, session_id: string}
22	     */
23	    public function execute(Professional $professional, array $data): Subscription|array
24	    {
25	        $subscription = Subscription::query()
26	            ->where('professional_id', $professional->id)
27	            ->whereNull('ended_at')
28	            ->first();
29	
30	        if (! $subscription) {
31	            throw ValidationException::withMessages([
32	                'subscription' => ['Professional has no active subscription.'],
33	            ]);
34	        }
35	
36	        if (! $subscription->isActive() && ! $subscription->isInGracePeriod()) {
37	            throw ValidationException::withMessages([
38	                'subscription' => ['Subscription is not active.'],
39	            ]);
40	        }
41	
42	        $newPlan = Plan::findOrFail($data['plan_id']);
43	
44	        // Enforce plan authorization by professional type
45	        $type = $professional->professional_type;
46	        if ($type === 'brand' && $newPlan->plan_key !== 'brands' && $newPlan->plan_key !== 'free') {
47	            throw ValidationException::withMessages([
48	                'plan_id' => ['This plan is not available for brand accounts.'],
49	            ]);
50	        }
51	        if ($type !== 'brand' && $newPlan->plan_key === 'brands') {
52	            throw ValidationException::withMessages([
53	                'plan_id' => ['This plan is only available for brand accounts.'],
54	            ]);
55	        }
56	
57	        if ($subscription->plan_id === $newPlan->id) {
58	            throw ValidationException::withMessages([
59	                'plan_id' => ['New plan is the same as current plan.'],
60	            ]);
61	        }
62	
63	        // Free -> Paid: need Stripe Checkout (no payment method on file)
64	        if ($subscription->isFreeInternal()) {
65	            return $this->billing->createCheckoutSession(
66	                $professional,
67	                $newPlan,
68	                $data['success_url'],
69	                $data['cancel_url'],
70	            );
71	        }
72	
73	        // Paid -> Free: cancel Stripe subscription, webhook handles free fallback
74	        if ($newPlan->plan_key === 'free') {
75	            $this->billing->cancelSubscriptionImmediately($subscription->stripe_subscription_id);
76	
77	            // The webhook for customer.subscription.deleted will:
78	            // 1. Set ended_at on this subscription
79	            // 2. Create a free internal subscription for affiliates
80	            return $subscription->fresh();
81	        }
82	
83	        // Paid -> Paid: update price on Stripe; customer.subscription.updated webhook
84	        // reconciles plan_id and cancel_at_period_end locally (same as paid->free path).
85	        $this->billing->updateSubscriptionPlan(
86	            $subscription->stripe_subscription_id,
87	            $newPlan,
88	        );
89	
90	        return $subscription->fresh();
91	    }
92	}
