3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Billing\Plan;
7	use App\Models\Billing\Subscription;
8	use App\Models\Billing\WebhookEvent;
9	use App\Models\Core\Professional\Professional;
10	use App\Services\Notifications\NotificationPublisher;
11	use App\Services\Professional\SiteProvisioningService;
12	use Carbon\Carbon;
13	use Illuminate\Http\JsonResponse;
14	use Illuminate\Http\Request;
15	use Illuminate\Support\Facades\DB;
16	use Illuminate\Support\Facades\Log;
17	use Illuminate\Support\Str;
18	use Stripe\Exception\SignatureVerificationException;
19	use Stripe\Webhook;
20	
21	// V2: Core. Processes Stripe Billing subscription lifecycle webhooks. Source of truth for subscription state.
22	class StripeWebhookController extends Controller
23	{
24	    use ValidatesStripeWebhookPayload;
25	    public function __invoke(Request $request): JsonResponse
26	    {
27	        $payload = $request->getContent();
28	        $sigHeader = $request->header('Stripe-Signature');
29	
30	        if (! $sigHeader) {
31	            return response()->json(['error' => 'Missing signature'], 400);
32	        }
33	
34	        $secret = config('services.stripe.webhook_secret');
35	
36	        if (! $secret) {
37	            return response()->json(['error' => 'No webhook secret configured'], 400);
38	        }
39	
40	        try {
41	            $event = Webhook::constructEvent($payload, $sigHeader, $secret);
42	        } catch (SignatureVerificationException) {
43	            Log::warning('Stripe billing webhook signature verification failed');
44	
45	            return response()->json(['error' => 'Invalid signature'], 400);
46	        } catch (\Exception $e) {
47	            Log::warning('Stripe billing webhook parse error', ['error' => $e->getMessage()]);
48	
49	            return response()->json(['error' => 'Invalid payload'], 400);
50	        }
51	
52	        if (! $this->validateEventStructure($event)) {
53	            return response()->json(['error' => 'Invalid payload structure'], 400);
54	        }
55	
56	        // Idempotency: firstOrCreate on the UNIQUE stripe_event_id. wasRecentlyCreated
57	        // distinguishes "won the race / first delivery" from "duplicate — skip".
58	        $webhookEvent = WebhookEvent::firstOrCreate(
59	            ['stripe_event_id' => $event->id],
60	            ['event_type' => $event->type, 'processed_at' => now()]
61	        );
62	
63	        if (! $webhookEvent->wasRecentlyCreated) {
64	            return response()->json(['received' => true]);
65	        }
66	
67	        // Payload is HMAC-verified; set via forceFill (not mass-assignment) to preserve $fillable restriction.
68	        $webhookEvent->forceFill(['payload' => json_decode($payload, true)])->save();
69	
70	        match ($event->type) {
71	            'customer.subscription.created' => $this->handleSubscriptionCreated($event->data->object, $event),
72	            'customer.subscription.updated' => $this->handleSubscriptionUpdated($event->data->object, $event),
73	            'customer.subscription.deleted' => $this->handleSubscriptionDeleted($event->data->object, $event),
74	            'invoice.paid' => $this->handleInvoicePaid($event->data->object, $event),
75	            'invoice.payment_failed' => $this->handleInvoicePaymentFailed($event->data->object, $event),
76	            'payment_method.detached' => $this->handlePaymentMethodDetached($event->data->object),
77	            default => Log::debug('Unhandled Stripe billing event', ['type' => $event->type]),
78	        };
79	
80	        return response()->json(['received' => true]);
81	    }
82	
83	    private function handleSubscriptionCreated(object $subscription, object $event): void
84	    {
85	        // Resolve professional: prefer stripe_customer_id lookup (tamper-proof),
86	        // fall back to metadata (set server-side by StripeBillingService).
87	        $stripeCustomerId = (string) ($subscription->customer ?? '');
88	        $professional = $stripeCustomerId
89	            ? Professional::where('stripe_customer_id', $stripeCustomerId)->first()
90	            : null;
91	
92	        if (! $professional) {
93	            $professionalId = $subscription->metadata?->sidest_professional_id ?? null;
94	            $professional = $professionalId ? Professional::find($professionalId) : null;
95	        }
96	
97	        if (! $professional) {
