78	    public function isInGracePeriod(): bool
79	    {
80	        if ($this->ended_at !== null) {
81	            return false;
82	        }
83	
84	        if ($this->status === self::STATUS_ACTIVE) {
85	            return true;
86	        }
87	
88	        if ($this->status === self::STATUS_PAST_DUE) {
89	            // Time-box grace: revoke entitlements after N days of failed payment.
90	            // current_period_end is when the billing period ended (= when payment first failed).
91	            // Guard for unit-test contexts where the config repository isn't bootstrapped.
92	            $graceDays = app()->bound('config')
93	                ? (int) config('sidest.billing.past_due_grace_days', 7)
94	                : 7;
95	
96	            return $this->current_period_end !== null
97	                && $this->current_period_end->greaterThan(now()->subDays($graceDays));
98	        }
99	
100	        return false;
101	    }
